public class AgeCalculator {

    public static int[] ageParts(java.time.LocalDate birth, java.time.LocalDate on) {
        java.time.Period p = java.time.Period.between(birth, on);
        return new int[] {p.getYears(), p.getMonths(), p.getDays()};
    }
}
